def bird_code(names):
    result = []
    for name in names:
        # Replace hyphens with spaces and split into words
        words = name.replace('-', ' ').split()

        if len(words) == 1:
            code = words[0][:4].upper()
        elif len(words) == 2:
            code = (words[0][:2] + words[1][:2]).upper()
        elif len(words) == 3:
            code = (words[0][0] + words[1][0] + words[2][:2]).upper()
        else:  # 4 or more words
            code = ''.join(word[0] for word in words[:4]).upper()

        result.append(code)

    return result
